# -*- coding: utf-8 -*-
"""Lecture et écriture du presse-papiers macOS avec exclusion des secrets."""
import threading
import uuid

import objc
from AppKit import NSPasteboard, NSPasteboardItem, NSPasteboardTypeString
from Foundation import NSData

MARQUE_COFFRE = "org.mesoutils.secret"
TYPES_EXCLUS = {MARQUE_COFFRE, "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                "org.nspasteboard.AutoGeneratedType"}


class SourceMac:
    def numero(self):
        with objc.autorelease_pool():
            return NSPasteboard.generalPasteboard().changeCount()

    def lire(self):
        with objc.autorelease_pool():
            planche = NSPasteboard.generalPasteboard()
            numero = planche.changeCount()
            if TYPES_EXCLUS.intersection(planche.types() or ()):
                return None, "exclu"
            texte = planche.stringForType_(NSPasteboardTypeString)
            if planche.changeCount() != numero:
                return None, "occupe"
            return (str(texte), None) if texte is not None else (None, "pas_de_texte")

    def ecrire(self, texte):
        _ecrire(texte)


def _ecrire(texte, jeton=None):
    with objc.autorelease_pool():
        planche = NSPasteboard.generalPasteboard()
        element = NSPasteboardItem.alloc().init()
        if not element.setString_forType_(texte, NSPasteboardTypeString):
            raise ValueError("Copie dans le presse-papiers impossible.")
        if jeton:
            donnees = NSData.dataWithBytes_length_(jeton, len(jeton))
            if not (element.setData_forType_(donnees, MARQUE_COFFRE)
                    and element.setData_forType_(donnees, "org.nspasteboard.ConcealedType")):
                raise ValueError("Impossible d’exclure ce secret de l’historique du presse-papiers.")
        planche.clearContents()
        if not planche.writeObjects_([element]):
            raise ValueError("Copie dans le presse-papiers impossible.")


def _effacer(jeton):
    with objc.autorelease_pool():
        planche = NSPasteboard.generalPasteboard()
        numero = planche.changeCount()
        donnees = planche.dataForType_(MARQUE_COFFRE)
        if donnees is not None and bytes(donnees) == jeton and planche.changeCount() == numero:
            planche.clearContents()


def copier_secret(texte, effacer_apres):
    jeton = uuid.uuid4().bytes
    _ecrire(texte, jeton)
    if effacer_apres:
        minuterie = threading.Timer(effacer_apres, _effacer, args=(jeton,))
        minuterie.daemon = True
        minuterie.start()
